# perf_dma_probe_50r_1bg_128.S — DMA bandwidth-latency probe: 1 background channels, 50% loads, 128 B
# Channel 0 times one 32 B load while channels 1..1 stream 128 B
# transfers (50% loads) as background traffic. CSR_DBG1 = (traffic phase
# cycles << 16) | probe cycles; background bytes = 512.
# Generated by npu-model/scripts/gen_dma_probe_programs.py.
# @TIMEOUT 400000
# @DRAM_BASE 0x90000000
# @PERF_REPORT

    LI    x5, 0x00000000
    DMA.CONFIG x5, 0
    LI    x12, 32
    LI    x13, 128
    LI    x8, 0
    LI    x10, 0x90100000
    LI    x1, 2048
    LI    x24, 0x90000000
    CSRRS x20, 0xC00, x0        # x20 = traffic phase start
    ADDI  x0, x0, 0             # keep CSR reads apart
    DMA.LOAD  x1, x24, x13, 1
    CSRRS x21, 0xC00, x0        # x21 = probe issue
    DMA.LOAD  x8, x10, x12, 0
    DMA.WAIT  0
    CSRRS x22, 0xC00, x0        # x22 = probe done
    ADDI  x0, x0, 0             # keep CSR reads apart
    DMA.WAIT  1
    DMA.LOAD  x1, x24, x13, 1
    DMA.WAIT  1
    DMA.LOAD  x1, x24, x13, 1
    DMA.WAIT  1
    DMA.LOAD  x1, x24, x13, 1
    DMA.WAIT  1
    CSRRS x23, 0xC00, x0        # x23 = traffic phase end
    SUB   x22, x22, x21         # probe cycles
    SUB   x23, x23, x20         # traffic phase cycles
    SLLI  x23, x23, 16
    OR    x22, x22, x23
    CSRRW x0,  0xC11, x22       # stash in CSR_DBG1
    ADDI  x30, x0, 1
    CSRW  x30, 0xC10
    ECALL
